class p{static async compress(r){try{const e=typeof r=="string"?r:JSON.stringify(r),o=new Blob([e]).stream().pipeThrough(new CompressionStream("gzip")),t=await new Response(o).arrayBuffer();return new Uint8Array(t)}catch(e){throw console.error("Compression Engine Error:",e),e}}static async decompress(r){try{const s=new Blob([r]).stream().pipeThrough(new DecompressionStream("gzip")),n=await new Response(s).text();return JSON.parse(n)}catch(e){return console.error("Decompression Engine Error:",e),null}}static getCompressionRatio(r,e){return r===0?"0%":((r-e)/r*100).toFixed(2)+"%"}}export{p as N};
